   %% Start
   clc;
   clear;
   close all;

   %% Dim
   W=0.55;     % max b
   L=0.55;     % max a

   dx=0.005;
   dy=0.005;

   m=L/dx;
   n=W/dy;

   A=600/(dx*dy*100*100);
   c=0.5;

   step=4;
   NN=20;      % max corners

   TT=zeros(m+2,n+2,NN/step-3);
   PP=zeros(m+2,n+2,NN/step-3);

   %% Thermal

   T0=30; % room temp
   Tinf=200;

   h=200;
   k=50;
   Bi=h*dx/k;
   alpha=0.000120;
   F=1/(4*(1+Bi));
   dt=F*(dx*dy)/alpha;
   dt=dt*0.99;

   F=alpha*dt/(dx*dy);

   t=dt;
   tkon=5;

   %% Corners loop
   for nn=4:step:NN

       T=ones(m+2,n+2)*T0;
       T(1,:)=0;
       T(m+2,:)=0;
       T(:,1)=0;
       T(:,n+2)=0;
       T1=T*0;

Team # 19064                                                               Page 15 of 18


       P=ones(size(T));

       N=nn;
       a=sqrt(A/(c*N*tan(pi/N)));
       b=sqrt(A*c/(N*tan(pi/N)));

       px=m+2;
       py=n+2;

       l=1:N;
       Xm=a*cos((2*l-1)*pi/N)/cos(pi/N);
       Ym=b*sin((2*l-1)*pi/N)/cos(pi/N);

       %% Shape

       for l=1:N
           if(l==1)
               f0=0-Ym(l)+Xm(l)*(Ym(l)-Ym(N))/(Xm(l)-Xm(N));

                    for i=-px/2+1:px/2
                        for j=-py/2+1:py/2
                            xt=j;
                            yt=i;
                            fx=(yt-Ym(l))-(xt-Xm(l))*(Ym(l)-Ym(N))/(Xm(l)-Xm(N));
                            if(fx*f0<0)
                                P(i+px/2,j+py/2)=-1;
                            end
                        end
                    end
             else
                    f0=0-Ym(l)+Xm(l)*(Ym(l)-Ym(l-1))/(Xm(l)-Xm(l-1));

                    for i=-px/2+1:px/2
                        for j=-py/2+1:py/2
                            xt=j;
                            yt=i;
                            fx=(yt-Ym(l))-(xt-Xm(l))*(Ym(l)-Ym(l-1))/(Xm(l)-Xm(l-1));
                            if(fx*f0<0)
                                P(i+px/2,j+py/2)=-1;
                            end
                        end
                    end
             end
       end

       sum=P*0-8;
       for i=2:px-1
           for j=2:py-1
               if(P(i,j)==1)
                    sum(i,j)=P(i-1,j)+P(i+1,j)+...
                            +P(i,j+1)+P(i,j-1)+...
                            +P(i-1,j+1)+P(i-1,j-1)+...
                            +P(i+1,j+1)+P(i+1,j-1);
               end
           end

Team # 19064                                                          Page 16 of 18


       end

       boundary=zeros(m*n,2);
       bc=1;

       P1=P;

       %% Boundary
       for i=2:px-1
           for j=2:py-1
               if(P(i,j)==1)
                    if(sum(i,j)<=7&&sum(i,j)~=-2)
                        P1(i,j)=0;
                        boundary(bc,:)=[i j];
                        bc=bc+1;

                         elseif(sum(i,j)==-2&&P(i-1,j)+P(i+1,j)+...
                             +P(i,j+1)+P(i,j-1)~=0)
                             P1(i,j)=-1;
                         elseif(sum(i,j)==-2&&P(i-1,j)+P(i+1,j)+...
                             +P(i,j+1)+P(i,j-1)==0)
                             P1(i,j)=0;
                         end
                   end
             end
       end
       P=P1;
       bc=bc-1;
       boundary(1:bc,:);
       PP(:,:,nn/step)=P;
   %     figure;
   %     pcolor(P)
   %     colorbar

   %     pause;
       %% Model
       V=T.*(P+1);

       sum1=P*0;

       px=m+2;
       py=n+2;
       for i=2:px-1
           for j=2:py-1
               sum1(i,j)=P(i-1,j)+P(i+1,j)+...
                        +P(i,j+1)+P(i,j-1);
           end
       end

       sum=0;

       %% Time
       t=dt;
       while t<tkon
           for i=1:m

Team # 19064                                                            Page 17 of 18


                  for j=1:n
                      py=j+1;
                      px=i+1;

                       sum=sum1(px,py);
                       v=V(px-1,py)+V(px+1,py)+V(px,py+1)+V(px,py-1);

                   if(P(px,py)==1)
                           T1(px,py)=F*(T(px-
   1,py)+T(px+1,py)+T(px,py+1)+T(px,py-1))+(1-4*F)*T(px,py);
                   elseif(P(px,py)==0)
                       switch (sum)
                           case 2
                               T1(px,py)=2/3*F*(v+2*Bi*Tinf)+(1-4*F-
   4/3*Bi*F)*T(px,py);
                           case 0
                               T1(px,py)=F*(v+2*Bi*Tinf)+(1-4*F-
   2*Bi*F)*T(px,py);
                           case -2
                               T1(px,py)=2*F*(v+2*Bi*Tinf)+(1-4*F-
   4*Bi*F)*T(px,py);
                       end
                   end
               end
           end

              T=T1;

              V=T.*(P+1);

              clc;
              nn
              t=t+dt

   %            figure;
   %        pcolor(T(1:m+1,1:n+1));
   %        shading interp;
   %        retazec=sprintf('Time=%g s',t);
   %        title(retazec);
   %        colorbar;
   %        pause(0.002);
          end

          %     T
          figure;
          pcolor(T(1:m+1,1:n+1));
          shading interp;
          retazec=sprintf('Time=%g s',t);
          title(retazec);
          colorbar;
   %        pause;

         TT(:,:,nn/step)=T;
   end
